"use client"

import type { SplitView } from "@/components/viewers/lib/split-types"
import { SplitViewer } from "@/components/viewers/split/split-viewer"
import { PdfViewer } from "@/components/ui/pdf-viewer"

const PDF_URL = "/samples/attention.pdf"

// A split result: named subdocuments, each owning a 1-indexed page range.
const SPLIT_RESULT: SplitView = {
  output: [
    { name: "Title & Abstract", pages: [1] },
    { name: "Introduction", pages: [2, 3] },
    { name: "Model Architecture", pages: [4, 5, 6] },
    { name: "Results", pages: [7, 8, 9] },
    { name: "References", pages: [10, 11] },
    { name: "Attention Visualizations", pages: [12, 13, 14, 15] },
  ],
}

/**
 * Split viewer block — the file + sidebar + legend system over a split result.
 * `SplitViewer` hands the document surface its chrome as `slots` (legend in
 * `top`, page ribbon as a `left` rail); the surface spreads them onto the
 * `PdfViewer`.
 */
export function SplitViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <SplitViewer
        result={SPLIT_RESULT}
        renderDocument={(handlers) => (
          <PdfViewer
            src={PDF_URL}
            bare
            downloadFileName="attention.pdf"
            slots={handlers.slots}
            onVisiblePageChange={handlers.onCurrentPageChange}
            onScrollProgressChange={handlers.onScrollProgressChange}
            className="h-full"
          />
        )}
      />
    </div>
  )
}

"use client"

import { useCallback, useMemo, useRef, useState, type ReactNode } from "react"
import { Loader2, Scissors } from "lucide-react"

import { segmentsPageCount, toSegments } from "@/lib/segments"
import { PageRibbon } from "@/components/ui/page-ribbon"
import { type PdfViewerSlots } from "@/components/ui/pdf-viewer"
import { SegmentLegend } from "@/components/ui/segment-legend"
import { useSegmentInteraction } from "@/components/ui/use-segment-interaction"
import { type SplitView } from "@/components/viewers/lib/split-types"

/**
 * Slots a document surface receives: the legend in `top`, the page ribbon as a
 * `left` rail. The surface spreads them onto its `PdfViewer`; the two are
 * independent regions, so neither disturbs the other.
 */
export interface SplitDocumentHandlers {
  onCurrentPageChange: (page: number) => void
  onScrollProgressChange: (progress: number) => void
  slots: PdfViewerSlots
}

export interface SplitViewerProps {
  result: SplitView | null
  isProcessing?: boolean
  renderDocument?: (handlers: SplitDocumentHandlers) => ReactNode
}

export function SplitViewer({
  result,
  isProcessing = false,
  renderDocument,
}: SplitViewerProps) {
  const [currentPage, setCurrentPage] = useState(1)
  const [scrollProgress, setScrollProgress] = useState(0)
  const interaction = useSegmentInteraction()
  const previewRef = useRef<HTMLDivElement | null>(null)
  const hasOutput = !!result && result.output.length > 0

  const segments = useMemo(
    () => toSegments(result?.output ?? []),
    [result?.output]
  )
  const pageCount = useMemo(() => segmentsPageCount(segments), [segments])

  const handleJumpToPage = useCallback((page: number) => {
    previewRef.current
      ?.querySelector<HTMLElement>(`[data-page-number="${page}"]`)
      ?.scrollIntoView({ behavior: "smooth", block: "start" })
  }, [])

  if (!hasOutput) {
    return (
      <div className="flex h-full flex-1 flex-col items-center justify-center gap-4 bg-muted px-8 text-muted-foreground">
        {isProcessing ? (
          <>
            <Loader2 className="h-12 w-12 animate-spin text-warning-foreground" />
            <p className="text-center text-base text-muted-foreground">
              Splitting...
            </p>
          </>
        ) : (
          <>
            <Scissors className="h-16 w-16 text-muted-foreground" />
            <p className="text-center text-base text-muted-foreground">
              Run split to see output
            </p>
            <p className="max-w-sm text-center text-sm text-muted-foreground">
              Upload a document, define subdocuments, then click Run Split
            </p>
          </>
        )}
      </div>
    )
  }

  // The legend mounts in the document's `top` slot; the ribbon is a `left` rail.
  const slots: PdfViewerSlots = {
    top: (
      <SegmentLegend
        segments={segments}
        currentPage={currentPage}
        interaction={interaction}
        onSelect={(segment) => {
          if (segment.pages.length) handleJumpToPage(segment.pages[0])
        }}
        columns={4}
        showUnusedToggle
      />
    ),
    left:
      pageCount > 0 ? (
        <div className="h-full overflow-auto border-r border-border bg-background px-3 py-6">
          <PageRibbon
            orientation="vertical"
            rows={[{ id: "split", segments }]}
            pageCount={pageCount}
            currentPage={currentPage}
            scrollProgress={scrollProgress}
            interaction={interaction}
            onSelectPage={handleJumpToPage}
            showTicks
          />
        </div>
      ) : undefined,
  }

  return (
    <div ref={previewRef} className="flex min-h-0 flex-1 bg-background">
      {renderDocument ? (
        renderDocument({
          onCurrentPageChange: setCurrentPage,
          onScrollProgressChange: setScrollProgress,
          slots,
        })
      ) : (
        <div className="flex h-full flex-1 items-center justify-center">
          <span className="text-sm text-muted-foreground">
            No document available
          </span>
        </div>
      )}
    </div>
  )
}

// Split result shapes (the structural subset the viewer needs), mirrored from
// the Retab dashboard's SplitView.

import type { PartitionChunk } from "@/components/viewers/lib/partition-types"

export interface SplitResult {
  name: string
  /** 1-indexed pages assigned to this subdocument. */
  pages: number[]
  /** Frontend-only overlay carried through by the split viewer. */
  partitions?: PartitionChunk[]
}

export interface SplitViewConsensus {
  choices?: SplitResult[][]
  likelihoods?: unknown[] | null
}

export interface SplitView {
  output: SplitResult[]
  consensus?: SplitViewConsensus | null
  usage?: { credits: number } | null
}

export function asSplitView(
  payload: { output?: unknown; consensus?: unknown; usage?: unknown } | null | undefined,
): SplitView | null {
  if (!payload || !Array.isArray(payload.output)) return null
  return {
    output: payload.output as SplitResult[],
    consensus: (payload.consensus ?? null) as SplitViewConsensus | null,
    usage: (payload.usage ?? null) as SplitView["usage"],
  }
}

export function getSplitVotes(
  splitView: SplitView | null | undefined,
  splitIndex: number,
): SplitResult[] {
  const choices = splitView?.consensus?.choices
  if (!choices?.length) return []
  return choices.flatMap((choice) => {
    const split = choice[splitIndex]
    return split ? [split] : []
  })
}

// Partition result shapes, mirrored from the Retab API / dashboard.

export interface PartitionChunk {
  key: string
  /** 1-indexed pages assigned to this chunk. */
  pages: number[]
}

export interface PartitionChunkLikelihood {
  key: number | null
  pages: number[]
}

export interface PartitionConsensus {
  choices: PartitionChunk[][]
  likelihoods: PartitionChunkLikelihood[] | null
}

export interface PartitionUsage {
  credits: number
}

export interface PartitionResult {
  output: PartitionChunk[]
  consensus: PartitionConsensus
  usage: PartitionUsage | null
}
